      }
    ]
  },
  "options": {
    "indexAxis": "y",
    "plugins": {
      "title": {
        "display": true,
        "text": "Quarterly Attainment Bullet Graph"
      },
      "legend": {
        "position": "bottom",
        "labels": {
          "filter": function(item, data) {
            return item.text !== "Target Marker Helper";
          }
        }
      },
      "tooltip": {
        "mode": "nearest",
        "intersect": false,
        "callbacks": {
          "label": function(context) {
            if (context.dataset.type === "scatter") {
              return "Target: " + context.parsed.x + "%";
            }
            if (context.dataset.label === "Low Band") {
              return "Band: 0–" + (context.raw) + "%";
            }
            if (context.dataset.label === "High Band") {
              var lower = (function() {
                var lows = [60,70,30,50,55,70,40,65];
                return lows[context.dataIndex];
              })();
              return "Band: " + lower + "–" + (lower + context.raw) + "%";
            }
            if (context.dataset.label === "Actual") {
              return "Actual: " + context.raw + "%";
            }
            return context.dataset.label + ": " + context.raw + "%";
          }
        }
      }
    },
    "scales": {
      "x": {
        "min": 0,
        "max": 100,
        "ticks": {
          "callback": function(value) {
            return value + "%";
          }
        },
        "grid": {
          "display": true
        },
        "stacked": true
      },
      "y": {
        "stacked": true
      }
    },
    "elements": {
      "point": {
        "pointStyle": [
          "line","line","line","line","line","line","line","line"
        ]
      }
    }
  },
  "plugins": [
    {
      "id": "targetCrosshair",
      "afterDatasetsDraw": function(chart, args, pluginOptions) {
        const {ctx, scales} = chart;
        const yScale = scales.y;
        const xScale = scales.x;
        const targetDs = chart.data.datasets.find(d => d.type === "scatter" && d.label === "Target");
        if (!targetDs) return;
        ctx.save();
        ctx.strokeStyle = "rgba(30,30,30,1)";
        ctx.lineWidth = 2;
        targetDs.data.forEach((pt, i) => {
          const x = xScale.getPixelForValue(pt.x);
          const y = yScale.getPixelForValue(i);
          const halfBar = (yScale.getPixelForValue(i - 0.4) - yScale.getPixelForValue(i + 0.4)) / 2;
          const yTop = y - halfBar * 0.6;
          const yBot = y + halfBar * 0.6;
          ctx.beginPath();
          ctx.moveTo(x - 6, yTop);
          ctx.lineTo(x + 6, yTop);
          ctx.moveTo(x - 6, yBot);
          ctx.lineTo(x + 6, yBot);
          ctx.moveTo(x, yTop);
          ctx.lineTo(x, yBot);
          ctx.stroke();
        });
        ctx.restore();
      }
    }
  ]
}

