    }
  },
  "plugins": [
    {
      "id": "facetGrid",
      "afterLayout": function(chart, args, opts) {
        // no-op; placeholder to ensure plugin order
      },
      "beforeDraw": function(chart, args, opts) {
        // Build facets mapping once
        if (!chart.$facetsBuilt) {
          const labels = chart.data.labels;
          const raw = {
            "Americas": {
              "Enterprise": [82.3,82.2,85.4,82.8,83.3,83.5,84.7,84.4,85.1,85.8,86.2,85.1],
              "Mid-market": [78.1,76.7,77.7,76.5,77.7,79.3,77.0,80.7,76.0,76.6,77.4,80.7],
              "SMB": [70.2,70.1,69.7,69.6,68.0,71.1,71.2,71.5,73.7,72.8,75.1,73.2]
            },
            "EMEA": {
              "Enterprise": [78.4,78.0,79.0,78.0,79.7,78.9,80.5,83.5,80.5,81.7,81.3,81.6],
              "Mid-market": [73.7,75.6,73.4,75.7,76.9,76.0,73.8,77.5,76.6,76.2,76.6,78.9],
              "SMB": [68.7,65.6,68.7,67.8,68.4,70.4,71.6,72.0,71.1,70.7,69.6,74.7]
            },
            "APAC": {
              "Enterprise": [79.7,78.9,80.7,80.3,78.9,83.9,83.6,83.2,82.1,83.9,82.6,84.7],
              "Mid-market": [73.4,74.7,73.4,72.9,75.2,72.8,73.8,74.9,73.4,73.0,75.8,76.1],
              "SMB": [67.7,64.7,68.2,66.7,67.4,66.2,67.7,67.8,68.2,71.0,71.2,69.8]
            }
          };
          chart.$facetConfig = {
            rows: ["Americas", "EMEA", "APAC"],
            cols: ["Enterprise", "Mid-market", "SMB"],
            data: raw
          };
          chart.$facetsBuilt = true;
        }

        const ctx = chart.ctx;
        const area = chart.chartArea;
        if (!area) return;

        const rows = chart.$facetConfig.rows;
        const cols = chart.$facetConfig.cols;
        const nRows = rows.length;
        const nCols = cols.length;

        // Compute cell sizes with small gaps
        const gap = 12;
        const cellW = (area.right - area.left - gap * (nCols - 1)) / nCols;
        const cellH = (area.bottom - area.top - gap * (nRows - 1)) / nRows;

        // Clear default dataset drawing (we'll custom-draw)
        ctx.save();
        ctx.fillStyle = chart.options.backgroundColor || "#ffffff00";
        ctx.fillRect(area.left, area.top, area.right - area.left, area.bottom - area.top);

        // Shared x scale across all cells (labels are same)
        const labels = chart.data.labels;
        const xMin = 0;
        const xMax = labels.length - 1;

        // Shared y domain
        const yMin = 60;
        const yMax = 90;

        // Axes style
        ctx.strokeStyle = "#ccc";
        ctx.lineWidth = 1;

        // Titles style
        ctx.fillStyle = "#333";
        ctx.font = "12px sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";

        // Draw each cell
        rows.forEach((rName, r) => {
          cols.forEach((cName, c) => {
            const x0 = area.left + c * (cellW + gap);
            const y0 = area.top + r * (cellH + gap);
            const x1 = x0 + cellW;
            const y1 = y0 + cellH;

            // Cell background
            ctx.save();
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(x0, y0, cellW, cellH);
            ctx.strokeStyle = "#e5e7eb";
            ctx.strokeRect(x0, y0, cellW, cellH);
            ctx.restore();

            // Row headers on left
            if (c === 0) {
              ctx.save();
              ctx.fillStyle = "#111827";
              ctx.font = "bold 12px sans-serif";
              ctx.textAlign = "right";
              ctx.textBaseline = "top";
              ctx.fillText(rName, x0 - 6, y0);
              ctx.restore();
            }

            // Column headers on top
            if (r === 0) {
              ctx.save();
              ctx.fillStyle = "#111827";
              ctx.font = "bold 12px sans-serif";
              ctx.textAlign = "center";
              ctx.textBaseline = "bottom";
              ctx.fillText(cName, x0 + cellW / 2, y0 - 6);
              ctx.restore();
            }

            // Scales per cell using shared domains
            const xScale = function(i) {
              if (xMax === xMin) return x0 + cellW / 2;
              const t = (i - xMin) / (xMax - xMin);
              return x0 + t * (cellW - 24) + 12; // padding 12px
            };
            const yScale = function(v) {
              if (yMax === yMin) return y0 + cellH / 2;
              const t = (v - yMin) / (yMax - yMin);
              return y1 - t * (cellH - 24) - 12; // padding 12px
            };

            // Gridlines (y)
            ctx.save();
            ctx.strokeStyle = "#f3f4f6";
            ctx.lineWidth = 1;
            const yTicks = [60, 70, 80, 90];
            yTicks.forEach(tv => {
              const yy = yScale(tv);
              ctx.beginPath();
              ctx.moveTo(x0 + 12, yy);
              ctx.lineTo(x1 - 12, yy);
              ctx.stroke();
            });
            ctx.restore();

            // X axis ticks and labels (shared x)
            ctx.save();
            ctx.fillStyle = "#6b7280";
            ctx.font = "10px sans-serif";
            ctx.textAlign = "center";
            ctx.textBaseline = "top";
            labels.forEach((lab, i) => {
              // show every other label to reduce clutter
              if (i % 2 !== 0) return;
              const xx = xScale(i);
              const yy = y1 - 10;
              ctx.fillText(lab, xx, yy);
            });
            ctx.restore();

            // Y axis labels at left of each cell
            ctx.save();
            ctx.fillStyle = "#6b7280";
            ctx.font = "10px sans-serif";
            ctx.textAlign = "right";
            ctx.textBaseline = "middle";
            [60, 70, 80, 90].forEach(tv => {
              const yy = yScale(tv);
              ctx.fillText(tv + "%", x0 + 8, yy);
            });
            ctx.restore();

            // Plot line
            const series = chart.$facetConfig.data[rName][cName] || [];
            ctx.save();
            ctx.strokeStyle = "#4c78a8";
            ctx.lineWidth = 2;
            ctx.beginPath();
            series.forEach((v, i) => {
              const xx = xScale(i);
              const yy = yScale(v);
              if (i === 0) ctx.moveTo(xx, yy);
              else ctx.lineTo(xx, yy);
            });
            ctx.stroke();

            // Points
            ctx.fillStyle = "#4c78a8";
            series.forEach((v, i) => {
              const xx = xScale(i);
              const yy = yScale(v);
              ctx.beginPath();
              ctx.arc(xx, yy, 2, 0, Math.PI * 2);
              ctx.fill();
            });
            ctx.restore();
          });
        });

        ctx.restore();

        // Prevent default datasets from drawing on top
        return true;
      }
    }
  ]
}

