          {"model_name":"Velo E-SUV","origin":"Europe","mpg":39.3,"horsepower":187,"weight_kg":1797,"acceleration_s":8.6},
          {"model_name":"Bison Pickup","origin":"USA","mpg":17.0,"horsepower":334,"weight_kg":2291,"acceleration_s":7.1},
          {"model_name":"Azure Sedan","origin":"USA","mpg":28.0,"horsepower":207,"weight_kg":1590,"acceleration_s":7.8},
          {"model_name":"Monsoon SUV","origin":"Asia","mpg":26.2,"horsepower":226,"weight_kg":1678,"acceleration_s":8.4}
        ];
        const mins = {};
        const maxs = {};
        axisKeys.forEach(k => {
          mins[k] = Math.min.apply(null, rawData.map(d => d[k]));
          maxs[k] = Math.max.apply(null, rawData.map(d => d[k]));
        });
        function scaleVal(k, v) {
          const min = mins[k], max = maxs[k];
          return max === min ? 0.5 : (v - min) / (max - min);
        }
        const colorByOrigin = {
          "USA": "#4c78a8",
          "Europe": "#f58518",
          "Asia": "#54a24b"
        };
        chart.data.datasets.forEach(ds => {
          // Parse model name and origin from label
          const match = ds.label.match(/^(.*) \((USA|Europe|Asia)\)$/);
          let origin = null;
          if (match) {
            origin = match[2];
            ds.borderColor = colorByOrigin[origin] || ds.borderColor;
            ds.pointBackgroundColor = ds.borderColor;
          }
          // Map dataset.data which is in raw order aligned with labels to scaled values
          const scaled = {};
          axisKeys.forEach((k, i) => {
            scaled[k] = scaleVal(k, ds.data[i]);
          });
          ds.data = axisKeys.map(k => scaled[k]);
        });
        // Update y scale to [0,1]
        if (chart.options && chart.options.scales && chart.options.scales.y) {
          chart.options.scales.y.min = 0;
          chart.options.scales.y.max = 1;
        }
      }
    }
  ]
