{
  "title": {
    "text": "Regional Mean Yield with Error Bars"
  },
  "tooltip": {
    "trigger": "axis",
    "axisPointer": {
      "type": "shadow"
    },
    "formatter": function (params) {
      var bar = params.find(function(p){ return p.seriesType === 'bar'; });
      var err = params.find(function(p){ return p.seriesType === 'custom'; });
      var name = bar ? bar.name : (params[0] && params[0].name) || '';
      var mean = bar ? bar.value : '';
      var low = err ? err.data[1][0] : '';
      var high = err ? err.data[1][1] : '';
      return name + '<br/>' +
             'Mean yield: ' + mean + ' tons<br/>' +
             'Lower: ' + low + ' tons<br/>' +
             'Upper: ' + high + ' tons';
    }
  },
  "grid": {
    "left": 60,
    "right": 20,
    "top": 60,
    "bottom": 60
  },
  "xAxis": {
    "type": "category",
