    "axisLabel": {
      "interval": 0
    }
  },
  "yAxis": {
    "type": "value",
    "name": "Mean yield (tons)"
  },
  "series": [
    {
      "type": "bar",
      "name": "Mean Yield",
      "data": [9.27, 6.8, 7.68, 8.48, 6.19, 4.6],
      "itemStyle": {
        "color": "#4c78a8"
      },
      "barMaxWidth": 50
    },
    {
      "type": "custom",
      "name": "Error",
      "renderItem": function (params, api) {
        var xIndex = api.value(0);
        var low = api.value(1);
        var high = api.value(2);
        var x = api.coord([xIndex, 0])[0];
        var lowPoint = api.coord([xIndex, low]);
        var highPoint = api.coord([xIndex, high]);
        var halfWidth = Math.min(api.size([1, 0])[0] * 0.2, 10);
        var style = api.style({
          stroke: '#333',
          fill: null
        });
        return {
          type: 'group',
          children: [
            {
              type: 'line',
              shape: { x1: x, y1: lowPoint[1], x2: x, y2: highPoint[1] },
              style: style
            },
            {
              type: 'line',
              shape: { x1: x - halfWidth, y1: lowPoint[1], x2: x + halfWidth, y2: lowPoint[1] },
              style: style
            },
            {
              type: 'line',
              shape: { x1: x - halfWidth, y1: highPoint[1], x2: x + halfWidth, y2: highPoint[1] },
              style: style
            }
          ]
        };
      },
