  "description": "Pie chart showing share_pct for each crop_variety.",
  "width": 400,
  "height": 400,
  "autosize": "pad",
  "title": "Crop Share by Variety",
  "data": [
    {
      "name": "table",
      "values": [
        { "crop_variety": "Sun Gold", "share_pct": 15 },
        { "crop_variety": "Blue Ridge", "share_pct": 26 },
        { "crop_variety": "Silver Seed", "share_pct": 17 },
        { "crop_variety": "Autumn Pearl", "share_pct": 23 },
        { "crop_variety": "Meadow Star", "share_pct": 19 }
      ],
      "transform": [
        {
          "type": "pie",
          "field": "share_pct"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "color",
      "type": "ordinal",
      "domain": {
        "data": "table",
        "field": "crop_variety"
      },
