      "name": "violinWidth",
      "type": "linear",
      "domain": [0, 1],
      "range": [0, {"signal": "bandwidth('x')"}]
    },
    {
      "name": "color",
      "type": "ordinal",
      "domain": {"data": "table", "field": "sensor_type"},
      "range": {"scheme": "category10"}
    }
  ],
  "axes": [
    {"orient": "bottom", "scale": "x", "title": "sensor_type"},
    {"orient": "left", "scale": "y", "title": "measurement_value"}
  ],
  "marks": [
    {
      "type": "group",
      "from": {
        "facet": {"data": "density", "name": "violinFacet", "groupby": "sensor_type"}
      },
      "encode": {
        "enter": {
          "x": {"scale": "x", "field": "sensor_type"},
          "width": {"signal": "bandwidth('x')"}
        }
      },
      "marks": [
        {
          "type": "area",
          "from": {"data": "violinFacet"},
          "encode": {
            "enter": {
              "interpolate": {"value": "monotone"},
              "fill": {"scale": "color", "field": {"parent": "sensor_type"}},
              "fillOpacity": {"value": 0.5},
              "stroke": {"scale": "color", "field": {"parent": "sensor_type"}},
              "strokeWidth": {"value": 1}
            },
            "update": {
              "y": {"scale": "y", "field": "value"},
              "x": {"signal": "scale('violinWidth', -datum.scaledDensity/2) + bandwidth('x')/2"},
              "x2": {"signal": "scale('violinWidth', datum.scaledDensity/2) + bandwidth('x')/2"}
            }
          }
        },
        {
          "type": "rect",
          "from": {
            "data": "summary",
            "filter": "datum.sensor_type == parent.sensor_type"
          },
          "encode": {
            "enter": {
              "x": {"signal": "bandwidth('x')*0.25"},
              "x2": {"signal": "bandwidth('x')*0.75"},
              "fill": {"value": "white"},
              "stroke": {"value": "black"}
            },
            "update": {
              "y": {"scale": "y", "field": "q3"},
              "y2": {"scale": "y", "field": "q1"}
            }
          }
        },
        {
          "type": "rule",
          "from": {
            "data": "summary",
            "filter": "datum.sensor_type == parent.sensor_type"
          },
          "encode": {
            "enter": {
              "stroke": {"value": "black"},
              "strokeWidth": {"value": 2}
            },
            "update": {
              "x": {"signal": "bandwidth('x')*0.25"},
              "x2": {"signal": "bandwidth('x')*0.75"},
              "y": {"scale": "y", "field": "median"}
            }
          }
        },
        {
          "type": "rule",
          "from": {
            "data": "summary",
            "filter": "datum.sensor_type == parent.sensor_type"
          },
          "encode": {
            "enter": {
              "stroke": {"value": "black"},
              "strokeWidth": {"value": 1}
            },
            "update": {
              "x": {"signal": "bandwidth('x')/2"},
              "x2": {"signal": "bandwidth('x')/2"},
              "y": {"scale": "y", "field": "min"},
              "y2": {"scale": "y", "field": "max"}
            }
          }
        }
      ]
    }
  ]
