    {
      "type": "rect",
      "from": {"data": "stacked"},
      "encode": {
        "enter": {
          "x": {"field": "x0"},
          "x2": {"field": "x1"},
          "y": {"field": "y0"},
          "y2": {"field": "y1"},
          "fill": {"scale": "color", "field": "brand_name"},
          "stroke": {"value": "white"},
          "strokeWidth": {"value": 1}
        },
        "update": {
          "opacity": {"value": 1}
        },
        "hover": {
          "opacity": {"value": 0.85}
        }
      }
    },
    {
      "type": "rule",
      "from": {"data": "segments"},
      "encode": {
        "enter": {
          "x": {"signal": "datum.x0_frac*width"},
          "y": {"value": 0},
          "y2": {"signal": "height"},
          "stroke": {"value": "#ddd"}
        }
      }
    },
    {
      "type": "text",
      "from": {"data": "segments"},
      "encode": {
        "enter": {
          "x": {"signal": "(datum.x0_frac + datum.segment_size_frac/2)*width"},
          "y": {"signal": "height + 15"},
          "text": {"field": "segment_name"},
          "align": {"value": "center"},
          "baseline": {"value": "top"},
          "fill": {"value": "black"}
        }
      }
    }
  ]
}

