      "calculate": "datum.segment_size_pct / datum.total_segment_size",
      "as": "segment_width_ratio"
    },
    {
      "window": [
        {"op": "sum", "field": "segment_width_ratio", "as": "x_end"}
      ],
      "sort": [{"field": "segment_name", "order": "ascending"}],
      "frame": [null, 0],
      "groupby": []
    },
    {
      "calculate": "datum.x_end - datum.segment_width_ratio",
      "as": "x_start"
    },
    {
      "window": [
        {"op": "sum", "field": "share_pct", "as": "y_end_raw"}
      ],
      "sort": [{"field": "brand_name", "order": "ascending"}],
      "groupby": ["segment_name"],
      "frame": [null, 0]
    },
    {
      "calculate": "datum.y_end_raw - datum.share_pct",
      "as": "y_start_raw"
    },
    {
      "calculate": "datum.y_start_raw/100",
      "as": "y_start"
    },
    {
      "calculate": "datum.y_end_raw/100",
      "as": "y_end"
    }
  ],
  "layer": [
    {
      "mark": {"type": "rect", "stroke": "white"},
      "encoding": {
        "x": {
          "field": "x_start",
          "type": "quantitative",
          "axis": null
        },
        "x2": {"field": "x_end"},
        "y": {
          "field": "y_start",
          "type": "quantitative",
          "axis": {"title": "Share within segment", "format": ".0%", "grid": true}
        },
        "y2": {"field": "y_end"},
        "color": {
          "field": "brand_name",
          "type": "nominal",
          "legend": {"title": "Brand"},
          "scale": {
            "domain": ["Alpha", "Beacon", "Compass", "Delta"],
            "range": ["#4c78a8", "#f58518", "#54a24b", "#e45756"]
          }
        },
        "tooltip": [
          {"field": "segment_name", "type": "nominal", "title": "Segment"},
          {"field": "brand_name", "type": "nominal", "title": "Brand"},
          {"field": "segment_size_pct", "type": "quantitative", "title": "Segment Size", "format": ".0%","aggregate": null}
        ]
      }
    },
    {
      "mark": {"type": "rule", "stroke": "#ddd"},
      "encoding": {
        "x": {"field": "x_end", "type": "quantitative", "axis": null},
        "size": {"value": 1}
      }
    },
    {
      "mark": {"type": "text", "dy": -4},
      "transform": [
        {"aggregate": [{"op": "max", "field": "x_start", "as": "x_start"},
                        {"op": "max", "field": "x_end", "as": "x_end"}],
         "groupby": ["segment_name"]},
        {"calculate": "(datum.x_start + datum.x_end)/2", "as": "x_mid"}
      ],
      "encoding": {
        "x": {"field": "x_mid", "type": "quantitative"},
        "y": {"value": 0},
        "text": {"field": "segment_name"},
        "tooltip": null
      }
    }
  ],
